import React from \"react\";
import { render, screen, waitFor } from \"@testing-library/react\";

import Pill, { PillType } from \"../../../../src/components/views/elements/Pill\";
import { stubClient } from \"../../../test-utils\";
import { MatrixClientPeg } from \"../../../../src/MatrixClientPeg\";

describe(\"Pill\", () => {
    beforeEach(() => {
        stubClient();
    });

    it(\"keeps the original URL on a message user pill\", async () => {
        const url = \"https://matrix.to/#/@alice:example.org?via=example.org\";
        (MatrixClientPeg.get().getProfileInfo as jest.Mock).mockResolvedValue({ displayname: \"Alice\" });
        render(<Pill type={PillType.UserMention} url={url} inMessage />);
        await waitFor(() => expect(screen.getByText(\"Alice\")).toBeTruthy());
        expect(screen.getByText(\"Alice\").closest(\"a\")?.getAttribute(\"href\")).toBe(url);
    });

    it(\"does not render an unrecognised link\", () => {
        const { container } = render(<Pill url=\"https://example.org/unknown\" inMessage />);
        expect(container.innerHTML).toBe(\"\");
    });
});
EOF
